#!/usr/bin/env python3
"""Pinned MLX server adapter for Apertus 1.5 reasoning delimiters.

mlx-lm 0.31.3 infers other families' reasoning tokens but omits Apertus's pair.
No vendor package, tokenizer or model bytes are modified. Only this owned server
process registers the delimiters already present in the loaded tokenizer.
"""
def thinking_tokens(tokenizer, fallback):
    vocab = tokenizer.get_vocab()
    start, end = '<|inner_prefix|>', '<|inner_suffix|>'
    if start in vocab and end in vocab:
        return start, end, (vocab[start],), (vocab[end],)
    return fallback(tokenizer)

def reasoning_prefix(output, tokenizer, *, enabled, generation_prompt):
    if not enabled or not generation_prompt:
        return output
    vocab = tokenizer.get_vocab()
    header, start, end = '<|assistant_start|>', '<|inner_prefix|>', '<|inner_suffix|>'
    if not all(t in vocab for t in (header, start, end)):
        return output
    if isinstance(output, str) and output.endswith(header):
        return output + start
    if isinstance(output, list) and output and output[-1] == vocab[header]:
        return output + [vocab[start]]
    return output

def main():
    from mlx_lm import tokenizer_utils
    fallback = tokenizer_utils._infer_thinking
    tokenizer_utils._infer_thinking = lambda tokenizer: thinking_tokens(tokenizer, fallback)
    original = tokenizer_utils.TokenizerWrapper.apply_chat_template
    def render(self, *args, **kwargs):
        output = original(self, *args, **kwargs)
        return reasoning_prefix(output, self, enabled=kwargs.get('enable_thinking', False), generation_prompt=kwargs.get('add_generation_prompt', False))
    tokenizer_utils.TokenizerWrapper.apply_chat_template = render
    from mlx_lm.server import main as serve
    serve()

if __name__ == '__main__':
    main()

