        elif len(term) > 4 and term.endswith('ed'):
            term = term[:-2]
        if len(term) > 4 and term.endswith('e'):
            term = term[:-1]
        result.append(term)
    return result

def rank(case, focus):
    cards = case['cards']
    if not cards:
        return []
    titles = [tokens(c['title']) for c in cards]
    bodies = [tokens(c['statement']) for c in cards]
    documents = [a + b for a, b in zip(titles, bodies)]
    df = {t: sum(t in d for d in documents) for d in documents for t in d}
    # Proposal-wide vocabulary should not produce a match for an unsupported topic.
    threshold = max(3, math.ceil(len(cards) * .6))
    query = {t for t in tokens(focus) if df.get(t, 0) < threshold}
    average_title = max(1, sum(map(len, titles)) / len(cards))
    average_body = max(1, sum(map(len, bodies)) / len(cards))
    result = []
    for index, card in enumerate(cards):
        score = 0
        for term in sorted(query):
            frequency = df.get(term, 0)
            idf = math.log(1 + (len(cards) - frequency + .5) / (frequency + .5))
            for field, average, weight in [(titles[index], average_title, TITLE_WEIGHT), (bodies[index], average_body, 1)]:
                tf = field.count(term)
                if tf:
                    score += weight * idf * tf * 2.2 / (tf + 1.2 * (.25 + .75 * len(field) / average))
        if score > 0:
            result.append({'id': card['id'], 'score': round(score, 8)})
    return sorted(result, key=lambda x: (-x['score'], x['id']))

def retrieve(case, plan):
    return [x['id'] for x in rank(case, plan['focus'])[:plan['limit']]] if plan['kind'] == 'EVIDENCE' else []

